import{_ as i,c as a,o as t,a2 as n}from"./chunks/framework.PGES7OoM.js";const p=JSON.parse('{"title":"destroyConfig","description":"Destroys a Curvy config and clears it when it is the ambient config.","frontmatter":{"title":"destroyConfig","description":"Destroys a Curvy config and clears it when it is the ambient config.","rawMarkdown":"---\\ntitle: destroyConfig\\ndescription: Destroys a Curvy config and clears it when it is the ambient config.\\n---\\n\\n# destroyConfig\\n\\nStops a config\'s timers, detaches API listeners, releases its prover, and clears the ambient reference when it points to that config.\\n\\n## Import\\n\\n```ts\\nimport { destroyConfig } from \\"@0xcurvy/curvy-sdk/config\\";\\n```\\n\\n## Usage\\n\\n```ts\\nawait destroyConfig({ config });\\n```\\n\\nCall `destroyConfig()` without parameters to destroy the current [ambient config](/sdk/config/#ambient-config).\\n\\n## Returns\\n\\n`Promise<void>`\\n\\n## Parameters\\n\\n### `config` (optional)\\n\\n- **Type:** `CurvyConfig`\\n\\nThe config to destroy. When omitted, the ambient config is used.\\n\\n```ts\\nawait destroyConfig({\\n  config, // [!code focus]\\n});\\n```\\n\\n## Errors\\n\\nThrows `NoCurvyConfigError` when no explicit or ambient config is available.\\n\\n## Related\\n\\n- [`createCurvyConfig`](/sdk/config/createCurvyConfig)\\n- [`getCurvyConfig`](/sdk/config/getCurvyConfig)\\n- [`setCurvyConfig`](/sdk/config/setCurvyConfig)\\n","rawMarkdownPath":"/_raw/sdk/config/destroyConfig.md","rawMarkdownTitle":"destroyConfig","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/config/destroyConfig.md"},"headers":[],"relativePath":"sdk/config/destroyConfig.md","filePath":"sdk/config/destroyConfig.md","lastUpdated":1786521734000}'),s={name:"sdk/config/destroyConfig.md"};function o(r,e,d,l,c,h){return t(),a("div",null,[...e[0]||(e[0]=[n("",18)])])}const f=i(s,[["render",o]]);export{p as __pageData,f as default};
